 woodley: { t: 'Peter Woodley. “Entangled experiences of class: The 1891 Queensland bush workers’ strike”. Australian Journal of Biography and History, no. 8, 2024. ANU Press.', u: 'https://doi.org/10.22459/ajbh.08.2024.07', short: 'Woodley, The 1891 Queensland bush workers’ strike', note: 'A peer-reviewed article with footnotes to Svensen’s “The Shearers’ War” and to newspapers of 1890 and 1891.' },
 qsaStrike: { t: 'Queensland State Archives. “Shear power: Shearer’s strike of 1891”. Stories from the Archives, 21 December 2021.', u: 'https://blogs.archives.qld.gov.au/2021/12/21/shear-power-shearers-strike-of-1891/', short: 'QSA, Shear power', note: 'Says employers cut wages and entitlements in late 1890 as the wool price fell. It gives thirteen arrests in March and also says 21 men boarded the boat to St Helena on 26 May.' },
