 hodesDouglas: { t: 'Jeremy Hodes. “squatter” label page, Queensland History (blog). Extract from his thesis on John Douglas, about Tooloombah station.', u: 'https://queenslandhistory.blogspot.com/search/label/squatter', short: 'Hodes, John Douglas and Tooloombah', note: 'Gives the Tooloombah mortgage, the transfer in 1867 and the insolvency in 1872, with footnotes. It also quotes a squatter on the panic of 1866.' },
 anuDalgety: { t: 'Noel Butlin Archives Centre, Australian National University. “Dalgety and Company Limited Brisbane Branch deposit” (administrative history).', u: 'https://archivescollection.anu.edu.au/index.php/dalgety-and-company-limited-brisbane-branch-deposit', short: 'ANU Archives, Dalgety and Company', note: 'Says Dalgety and Company Limited was registered in London on 29 April 1884 and opened branches in Rockhampton (1891) and Brisbane (1894). The date for Townsville (1896) was read as a search-tool excerpt.' },
