 anuNZLM: { t: 'Noel Butlin Archives Centre, Australian National University. “New Zealand Loan and Mercantile Agency Company Rockhampton Branch deposit” (administrative history).', u: 'https://archivescollection.anu.edu.au/index.php/new-zealand-loan-and-mercantile-agency-company-rockhampton-branch-deposit', short: 'ANU Archives, New Zealand Loan and Mercantile Agency', note: 'Says the company was registered in England in April 1865, opened Brisbane and Rockhampton branches in 1884, suspended business in July 1893 and was reconstructed on 10 May 1894.' },
 anuGM: { t: 'Noel Butlin Archives Centre, Australian National University. “Goldsbrough Mort and Company Head Office records” and the item “Correspondence from Rockhampton Manager requesting further advances to continue business”, June 1890.', u: 'https://archivescollection.anu.edu.au/index.php/correspondence-to-goldsbrough-mort-and-company-requesting-further-advances-to-continue-business', short: 'ANU Archives, Goldsbrough Mort and Company', note: 'The head office history says the company was formed in 1888 when R. Goldsbrough and Company, a Melbourne wool-broking firm founded in 1848, acquired Mort and Company of Sydney. The June 1890 item is a catalogue entry that was not opened.' + EXC },
 anuSAIC: { t: 'Noel Butlin Archives Centre, Australian National University. “The Scottish Australian Investment Company Limited” (authority record).', u: 'https://archivescollection.anu.edu.au/index.php/scottish-australian-investment-company-limited', short: 'ANU Archives, Scottish Australian Investment Company', note: 'Says the firm was set up in Aberdeen in 1840, began in Australia in 1841 and was incorporated in England on 27 October 1856.' },
 jcuBowen: { t: 'James Cook University Library Special Collections. “Bowen Downs Station Records”.', u: 'https://libserver.jcu.edu.au/specials/Archives/bowen.html', short: 'JCU Library, Bowen Downs station records', note: 'Says the Scottish-Australian Company provided the capital for Bowen Downs and that Nat Buchanan was the first manager. It lists shearers’ and men’s wage ledgers from 1872 to 1948.' },
