 muttaburra: { t: 'Muttaburra (community website). “Pastoral History of the Aramac Shire”, adapted from text by Lesley Cowper.', u: 'https://www.muttaburra.com/historical-milestones/pastoral-history-of-the-aramac-shire/', short: 'Muttaburra, Pastoral history of the Aramac Shire', note: 'A local history without footnotes. It gives the Landsborough River Company shares, the stock numbers at Bowen Downs and the losses in the drought to 1902.' },
 wikiBowen: { t: '“Bowen Downs Station”. Wikipedia.', u: 'https://en.wikipedia.org/wiki/Bowen_Downs_Station', short: 'Wikipedia, Bowen Downs Station', note: 'Names Iningai as the Traditional Owners and Nat Buchanan as the first manager. Its claim about blackbirded South Sea Islander labour rests on one item that was not read.' },
