 qutBoA: { t: 'QUT Digital Collections. “Bank of Australasia, Ipswich, Queensland”.', u: 'https://digitalcollections.qut.edu.au/6737/', short: 'QUT, Bank of Australasia, Ipswich', note: 'Gives 7 November 1853 as the opening of the bank’s Ipswich branch.' + EXC },
 adbDeuchar: { t: 'Australian Dictionary of Biography. “Deuchar, John”, life summary.', u: 'https://adb.anu.edu.au/lifesummary/deuchar-john-3404', short: 'ADB, John Deuchar (life summary)', note: 'The excerpt says Deuchar worked for the North British Australasian Company from 1842 to 1855 and managed Goomburra and Rosenthal.' + EXC },
 adbMorehead: { t: 'Australian Dictionary of Biography. “Morehead, Robert Archibald Alison”.', u: 'https://adb.anu.edu.au/biography/morehead-robert-archibald-alison-2478', short: 'ADB, Robert Archibald Alison Morehead', note: 'The excerpt says he managed the Scottish Australian Investment Company in Australia from 1841.' + EXC },
 anuBurnsPhilp: { t: 'Noel Butlin Archives Centre, Australian National University. “Changing Times”, in the exhibition on Burns Philp.', u: 'https://archives.anu.edu.au/exhibitions/merchants-pacific-rise-and-fall-burns-philp/changing-times', short: 'ANU Archives, Burns Philp, Changing Times', note: 'Says two of Burns Philp’s three banks, the Queensland National Bank and the Bank of North Queensland, collapsed in the 1890s.' + EXC },
 atfMitchell: { t: 'Lynley A. Wallis and Heather Burke. “Mitchell Pastoral District”. Archaeology on the Frontier.', u: 'https://archaeologyonthefrontier.com/pastoral-districts/mitchell/', short: 'Wallis and Burke, Mitchell district', note: 'The first runs of 1862, the finance for Bowen Downs from the Scottish Australian Investment Company, and a mass killing in 1866 linked to Bowen Downs and Aramac. It names Alexander Gordon, not Nat Buchanan, as first manager.' },
 atfBurke: { t: 'Lynley A. Wallis and Heather Burke. “Burke Pastoral District”. Archaeology on the Frontier.', u: 'https://archaeologyonthefrontier.com/pastoral-districts/burke/', short: 'Wallis and Burke, Burke district', note: 'Says run holders had to stock the land before applying to lease it, and that the first pastoralists were often backed by finance from the big cities. It mentions the Landsborough River Company at Beamesbrook by 1865.' },
 atfKennedy: { t: 'Lynley A. Wallis and Heather Burke. “Kennedy Pastoral District”. Archaeology on the Frontier.', u: 'https://archaeologyonthefrontier.com/pastoral-districts/kennedy/', short: 'Wallis and Burke, Kennedy district', note: 'The first runs of 1861 and the mortgage takeover of Inkerman in 1864.' },
 atfWarrego: { t: 'Lynley A. Wallis and Heather Burke. “Warrego Pastoral District”. Archaeology on the Frontier.', u: 'https://archaeologyonthefrontier.com/pastoral-districts/warrego/', short: 'Wallis and Burke, Warrego district', note: 'The first runs of 1861 to 1863 and the loss of Joseph Fleming’s runs.' }
